// FizzBuzz con un orden de preguntas equivocado (mirá qué pasa en el 15)
let linea = "";
for (let i = 1; i <= 15; i++) {
  if (i % 3 === 0) {
    linea += "Fizz ";
  } else if (i % 5 === 0) {
    linea += "Buzz ";
  } else if (i % 15 === 0) {
    linea += "FizzBuzz ";
  } else {
    linea += i + " ";
  }
}
console.log(linea);

// FizzBuzz: lo más específico primero (múltiplo de 15), después 3, después 5
let linea = "";
let soloFizz = 0, soloBuzz = 0, ambos = 0, numeros = 0; // acumuladores para probar el resultado

for (let i = 1; i <= 100; i++) {
  if (i % 15 === 0) {
    linea += "FizzBuzz ";
    ambos += 1;
  } else if (i % 3 === 0) {
    linea += "Fizz ";
    soloFizz += 1;
  } else if (i % 5 === 0) {
    linea += "Buzz ";
    soloBuzz += 1;
  } else {
    linea += i + " ";
    numeros += 1;
  }
}

console.log(linea);
console.log("Fizz:", soloFizz, "Buzz:", soloBuzz, "FizzBuzz:", ambos, "números:", numeros);
console.log("Suma de control:", soloFizz + soloBuzz + ambos + numeros);

// Otra forma: armar la palabra por partes, sin preguntar por el 15
let linea = "";
for (let i = 1; i <= 30; i++) {
  let palabra = "";
  if (i % 3 === 0) palabra += "Fizz";
  if (i % 5 === 0) palabra += "Buzz";
  if (palabra === "") palabra = i;   // si no sumó nada, queda el número
  linea += palabra + " ";
}
console.log(linea);

// Suma de dígitos con un acumulador: n % 10 es el último dígito, Math.floor(n / 10) lo descarta
let n = 12345;
let suma = 0;                         // acumulador: arranca en 0, el elemento neutro de la suma
while (n > 0) {
  const ultimo = n % 10;              // el dígito de más a la derecha
  suma += ultimo;
  n = Math.floor(n / 10);             // quita ese dígito
  console.log("quedó n =", n, "| último =", ultimo, "| suma =", suma);
}
console.log("Suma de dígitos:", suma);

// Probar con casos que rompen cosas: cero, un dígito, ceros en el medio, negativo
for (const original of [0, 7, 10, 90817, -482]) {
  let n = Math.abs(original);        // para el negativo, trabajamos con su valor sin signo
  let suma = 0;
  while (n > 0) {
    suma += n % 10;
    n = Math.floor(n / 10);
  }
  console.log(original, "->", suma);
}
// Un caso borde distinto: números enormes pierden dígitos antes de empezar
