// ¿Es primo? Probar divisores desde 2 hasta la raíz cuadrada
for (const n of [0, 1, 2, 9, 25, 49, 97, 91, 1000003]) {
  let primo = n >= 2;                        // 0 y 1 no son primos por definición
  let intentos = 0;
  for (let d = 2; d * d <= n && primo; d++) {
    intentos += 1;
    if (n % d === 0) primo = false;          // encontramos un divisor: ya no hace falta seguir
  }
  console.log(n, primo ? "primo" : "no es primo", "| divisiones probadas:", intentos);
}

// Todos los primos hasta un tope, y cuántas divisiones se ahorra la raíz cuadrada
const tope = 100;
let encontrados = "";
let cantidad = 0;
let divisionesSqrt = 0, divisionesIngenuo = 0;

for (let n = 2; n <= tope; n++) {
  // Versión ingenua: probar todos los divisores de 2 a n - 1 (solo para contar)
  for (let d = 2; d < n; d++) {
    divisionesIngenuo += 1;
    if (n % d === 0) break;
  }
  // Versión con raíz cuadrada
  let primo = true;
  for (let d = 2; d * d <= n; d++) {
    divisionesSqrt += 1;
    if (n % d === 0) { primo = false; break; }
  }
  if (primo) { encontrados += n + " "; cantidad += 1; }
}
console.log(encontrados);
console.log("Primos hasta", tope + ":", cantidad);
console.log("Divisiones probadas -> ingenuo:", divisionesIngenuo, "| raíz cuadrada:", divisionesSqrt);

// Invertir una cadena: recorrer de atrás para adelante y acumular
for (const texto of ["hola", "Logística", "a", ""]) {
  let invertido = "";                         // acumulador de texto: arranca vacío
  for (let i = texto.length - 1; i >= 0; i--) {
    invertido += texto[i];                    // texto[i] es el carácter en la posición i (la primera es la 0)
  }
  console.log(JSON.stringify(texto), "->", JSON.stringify(invertido));
}

// Un caso borde que no se ve a simple vista: ¿cuántos «caracteres» tiene "a𝄞"? (𝄞 es la clave de sol)
