for (let i = texto.length - 1; i >= 0; i--) roto += texto[i];
console.log("con índices:", roto.length, "unidades, pero el símbolo ya no es válido");

// Invertir con for...of: anteponer cada carácter al acumulador
let invertido = "";
for (const c of texto) invertido = c + invertido;
console.log("con for...of:", invertido);

// Contar vocales: pasar a minúscula y preguntar si cada letra está en la lista de vocales
